function bindingFor(actor, actionId) {
  const lookupId = actionId === 'techArmorDetonate' ? 'techArmor' : actionId;
  return CHRONICLE_SIGNATURE_BINDINGS.find(binding => binding.mediaId === actor?.mediaId && binding.actionId === lookupId);
}
