  const binding = bindingFor(actor, actionId);
  return !!binding && actor.buildId === binding.buildId && actor.powerCatalogIds?.includes(binding.catalogId) === true
    && (actionId !== 'techArmorDetonate' || actor.mediaId === 'ME3');
