  if(target?.kind!=='vehicle')return world.interact();
  const leaving=world.isVehicleMounted(),result=leaving?world.leaveVehicle():world.boardVehicle();
  if(!result.ok){const reasons={'no-safe-ground':'Aucun espace libre pour débarquer ici.','too-far':'Rapprochez-vous du Mako.','blocked':'Le passage vers le Mako est bloqué.','mode':'Le Mako est disponible pendant l’exploration.'};return toast(reasons[result.reason]||'Le Mako est inaccessible ici.',true);}
  releaseTouch();
  state.position=world.getPosition();hudStamp='';autosave();renderHUD();
